CREATE SCHEMA IF NOT EXISTS public;
 SET search_path TO public; 

CREATE TABLE "users" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"account" VARCHAR(100) NOT NULL,
	"provider" VARCHAR(50) NOT NULL,
	"password_hash" VARCHAR(255) NOT NULL,
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updated_at" TIMESTAMPTZ,
	PRIMARY KEY("id"),
	UNIQUE ("provider", "account")
);
COMMENT ON TABLE "users" IS '使用者核心資料表 @oso={"rules":[{"actor":"admin","actions":["read","create","update","delete"],"condition":null},{"actor":"user","actions":["read","update"],"condition":{"field":"id","operator":"eq","target":"actor.id"}}]}';
COMMENT ON COLUMN "users"."id" IS '流水號';
COMMENT ON COLUMN "users"."account" IS '用戶帳號 (email/phone/google/github/line/etc.) @validate="required,email|e164"';
COMMENT ON COLUMN "users"."provider" IS '登入提供商 (email/phone/google/github/line/etc.)';
COMMENT ON COLUMN "users"."password_hash" IS '密碼雜湊 @type=encode @alias=password @rule=hide';
COMMENT ON COLUMN "users"."is_active" IS '是否啟用';
COMMENT ON COLUMN "users"."created_at" IS '資料建立時間 @type=auto_createdtime';
COMMENT ON COLUMN "users"."updated_at" IS '資料更新時間 @type=auto_updatedtime';
CREATE INDEX "user_account_index" ON "users" ("account");

