-- AUTO_UPDATE_TIMESTAMP_TRIGGERS


CREATE OR REPLACE FUNCTION "f_auto_update_users_updated_at"() RETURNS trigger AS $$
BEGIN
  NEW."updated_at" = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "trg_auto_update_users_updated_at"
BEFORE UPDATE ON "users"
FOR EACH ROW EXECUTE FUNCTION "f_auto_update_users_updated_at"();


